   431  static int unhex4(char* hex) {
   432    int r = 0;
   433    for (int i=0; i<4; i++) {
   434      char c = *hex++;
   435      int n;
   436      if ('0' <= c && c <= '9') n = c - '0';
   437      else if ('a' <= c && c <= 'f') n = c - 'a' + 10;
   438      else if ('A' <= c && c <= 'F') n = c - 'A' + 10;
   439      else return -1;
   440      r <<= 4;
   441      r |= n;
   442    }
   443    return r;
   444  }
