   116      *out++ = 0x80 + ((codepoint & 0x00003F));
   117    }
   118    assert(out - start == jvp_utf8_encode_length(codepoint));
   119    return out - start;
   120  }
   121
   122  // characters with White_Space property in:
   123  // https://www.unicode.org/Public/UCD/latest/ucd/PropList.txt
   124  int jvp_codepoint_is_whitespace(int c) {
   125    return
   126      (c >= 0x0009 && c <= 0x000D) || // <control-0009>..<control-000D>
   127      c == 0x0020                  || // SPACE
   128      c == 0x0085                  || // <control-0085>
   129      c == 0x00A0                  || // NO-BREAK SPACE
   130      c == 0x1680                  || // OGHAM SPACE MARK
   131      (c >= 0x2000 && c <= 0x200A) || // EN QUAD..HAIR SPACE
   132      c == 0x2028                  || // LINE SEPARATOR
   133      c == 0x2029                  || // PARAGRAPH SEPARATOR
   134      c == 0x202F                  || // NARROW NO-BREAK SPACE
   135      c == 0x205F                  || // MEDIUM MATHEMATICAL SPACE
   136      c == 0x3000                     // IDEOGRAPHIC SPACE
   137      ;
   138  }
